test('conflito não bloqueia criação e indicadores são recalculados', () => { const first = { ...obras[0], id: 'a', mestresPlanejados: [] }; const second = { ...obras[0], id: 'b', mestresPlanejados: [] }; const item = { localId: 'a1', mestreKey: 'dilamar', nome: 'DILAMAR', inicio: '2026-10-05', tempoPlanejado: 7 }; const once = addMestrePlanejadoLocal([first, second], 'a', item); const twice = addMestrePlanejadoLocal(once, 'b', { ...item, localId: 'b1' }); assert.equal(twice[1].mestresPlanejados.length, 1); assert.ok(calculateIndicators(twice).conflicts > 0); });
