test('cores de mestre não usam as cores claras reservadas da obra', () => { const reserved = new Set(['#d7eafa', '#f8d9d5', '#fff0c9']); MESTRE_COLORS.forEach((color) => assert.equal(reserved.has(color.background), false)); });
