test('drop em obra em dia exige início no prazo; obra atrasada aceita extensão; finalizada recusa', () => { const base = { ...obras[0], inicioPlanejado: '2026-10-01', tempoPlanejado: 2, mestresPlanejados: [] }; assert.equal(isValidMasterDropStart(base, '2026-10-04', '2026-10-02'), false); assert.equal(isValidMasterDropStart(base, '2026-10-04', '2026-10-05'), true); assert.equal(isValidMasterDropStart({ ...base, status: 'FINALIZADA' }, '2026-10-02', '2026-10-05'), false); assert.equal(getDropPlanningStart({ obra: base, zoom: 'day', targetDateOrPeriod: '2026-10-04', hoje: '2026-10-05' }), '2026-10-04'); });
