test('agrega estados semanais consecutivos', () => { const obra = { ...obras[0], inicioPlanejado: '2026-10-05', tempoPlanejado: 1, status: 'EM ANDAMENTO' as const, mestresPlanejados: [{ localId: 'm', nome: 'DILAMAR', inicio: '2026-10-06', tempoPlanejado: 2 }], hoje: '2026-10-09' }; const aggregate = getBucketTimelineAggregate(obra, '2026-10-05', 7); assert.deepEqual(aggregate.states, [{ type: 'planned', offset: 0, days: 1 }, { type: 'mastered', offset: 1, days: 2 }, { type: 'overdue', offset: 3, days: 2 }, { type: 'attention', offset: 5, days: 2 }]); });
test('agrega mestre semanal com offset', () => { const masters = [{ localId: 'm', nome: 'DILAMAR', inicio: '2026-10-09', tempoPlanejado: 3 }]; assert.deepEqual(getMasterSegmentsInBucket(masters, '2026-10-05', 7).map(({ offset, days }) => ({ offset, days })), [{ offset: 4, days: 3 }]); });
