test('tabela finalizada compartilha a geometria canônica', () => { const table = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/components/ContractTextTable.tsx'), 'utf8'); const styles = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/styles/cronograma-obras.css'), 'utf8'); assert.match(table, /variant = "finished"/); assert.match(styles, /\.co-text-head, \.co-text-row \{ display: grid; grid-template-columns: var\(--co-left-columns\)/); assert.match(styles, /\.co-text-table \.co-text-head, \.co-text-table \.co-text-row \{ grid-template-columns: var\(--co-left-columns\)/); });
test('tipo de obra agrupa Pública, Privada e desconhecida sem perder a ordem interna', () => { const groups = groupObrasByContract([{ ...fixtureObra('p1'), contratoId: 'publica-1', contratoNome: 'Pública 1' }, { ...fixtureObra('v1'), contratoId: 'privada-1', contratoNome: 'Privada 1' }, { ...fixtureObra('p2'), contratoId: 'publica-2', contratoNome: 'Pública 2' }, { ...fixtureObra('u1'), contratoId: 'sem-tipo', contratoNome: 'Sem tipo' }]); const contratos = new Map(groups.map((group) => [group.id, { tipoObra: group.id.startsWith('publica') ? 'Pública' : group.id.startsWith('privada') ? 'Privada' : null }])); const typed = groupContractGroupsByWorkType(groups, contratos as any); assert.deepEqual(typed.map((item) => [item.label, item.groups.map((group) => group.id)]), [['OBRAS PÚBLICAS', ['publica-1', 'publica-2']], ['OBRAS PRIVADAS', ['privada-1']], ['SEM CLASSIFICAÇÃO', ['sem-tipo']]]); });
test('tipo de obra vem apenas do raw do contrato e preserva valor ausente como neutro', () => { const diagnostics: string[] = []; const publico = adaptRawContract({ id: 'publico', exists: true, data: { obraV2Id: 'v2', raw: { nome: 'P', tipoObra: 'Pública', subitems: [] } } }, diagnostics); const desconhecido = adaptRawContract({ id: 'desconhecido', exists: true, data: { obraV2Id: 'v2', raw: { nome: 'U', subitems: [] } } }, diagnostics); assert.equal(publico!.tipoObra, 'Pública'); assert.equal(desconhecido!.tipoObra, null); });
test('divisores de tipo são estruturais, leves e mantêm a ordem sem alterar os calendários', () => { const gantt = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/components/GanttGrid.tsx'), 'utf8'); const table = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/components/ContractTextTable.tsx'), 'utf8'); const page = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/CronogramaObrasPage.tsx'), 'utf8'); const styles = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/styles/cronograma-obras.css'), 'utf8'); assert.match(gantt, /workTypeGroups\.flatMap/); assert.match(gantt, /co-work-type-divider__fixed/); assert.match(gantt, /co-work-type-divider__timeline/); assert.doesNotMatch(gantt, /co-work-type-divider[^\n]*ObraCells/); assert.doesNotMatch(gantt, /co-work-type-divider[^\n]*(co-day-cell|co-week-cell|co-month-cell)/); assert.match(table, /sectionExpanded && workTypeGroups\.flatMap/); assert.match(page, /co-view-switch co-zoom-switch/); assert.match(page, /onClick=\{\(\) => changeZoom\(value\)\}/); assert.match(styles, /\.co-work-type-divider__fixed/); assert.match(styles, /\.co-work-type-divider__timeline/); assert.match(styles, /pointer-events: none/); });
test('header, contrato e LOTE usam as oito colunas canônicas na mesma ordem', () => { const gantt = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/components/GanttGrid.tsx'), 'utf8'); const columns = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/domain/obraGridColumns.ts'), 'utf8'); assert.match(columns, /OBRA_EXPANDED_COLUMNS[\s\S]*nomeContrato[\s\S]*obra[\s\S]*contrato[\s\S]*mestres[\s\S]*status[\s\S]*empresa[\s\S]*inicio[\s\S]*dias/); assert.match(gantt, /<span>Nome contrato<\/span>[\s\S]*<span>[\s\S]*Obra[\s\S]*<span>Contrato<\/span>[\s\S]*<span>Mestres<\/span>[\s\S]*<span>Status<\/span>[\s\S]*<span>Emp\.<\/span>[\s\S]*<span>In\u00edcio<\/span>[\s\S]*<span>Dias<\/span>/); assert.match(gantt, /co-contract-name-flat[\s\S]*co-work-name[\s\S]*co-contract-number[\s\S]*co-masters-cell[\s\S]*<StatusBadge status=\{obra\.status\}[\s\S]*obra\.empresa[\s\S]*formatDateShort\(obra\.inicioPlanejado\)[\s\S]*obra\.tempoPlanejado/); assert.match(gantt, /co-contract-name[\s\S]*group\.obras\.length[\s\S]*co-contract-number[\s\S]*co-contract-masters[\s\S]*StatusBadge status=\{contrato\?\.status/); assert.doesNotMatch(gantt, /<span aria-hidden="true"\s*\/>/); });
test('modo DIAS compartilha a mesma largura anual entre cabe\u00e7alho e corpo, com grade CSS sem 365 c\u00e9lulas por linha', () => { const styles = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/styles/cronograma-obras.css'), 'utf8'); const gantt = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/components/GanttGrid.tsx'), 'utf8'); assert.match(styles, /\.co-zoom--day\s*\{[^}]*--co-day-width:\s*24px;[^}]*--co-timeline-width:\s*8760px/); assert.match(styles, /\.co-gantt-header\s*\{[^}]*grid-template-columns:\s*var\(--co-left-width\) var\(--co-timeline-width\)/); assert.match(styles, /\.co-grid-row\s*\{[^}]*grid-template-columns:\s*var\(--co-left-width\) var\(--co-timeline-width\)/); assert.match(styles, /\.co-day-timeline, \.co-day-resource-timeline\s*\{[^}]*background:\s*var\(--co-day-grid\)/); assert.doesNotMatch(styles, /\.co-day-timeline, \.co-day-resource-timeline\s*\{[^}]*background-image:/); assert.match(gantt, /function dailyGridStyle/); assert.match(gantt, /zoom === "day"[\s\S]*co-day-timeline/); assert.match(gantt, /className="co-day-resource-timeline" style=\{dailyGridStyle\(days, null\)\}/); });
test('DIAS e SEMANAS montam uma timeline CSS no contrato e em cada LOTE', () => { const lote1 = { ...fixtureObra('lote-grade-1'), contratoId: 'contrato-grade', contratoNome: 'Contrato grade' }; const lote2 = { ...fixtureObra('lote-grade-2'), contratoId: 'contrato-grade', contratoNome: 'Contrato grade' }; const contrato = { id: 'contrato-grade', nome: 'Contrato grade', empresa: '', status: 'PENDENTE', numeroContrato: null, ano: null, inicio: null, fim: null, tipoObra: null, confirmacaoRecurso: null, ordemInicio: null, obraV2Id: null, rawDocument: null, obras: [lote1, lote2] }; const props = { view: 'obras' as const, years: [2026], obras: [lote1, lote2], contratos: new Map([[contrato.id, contrato]]), workloads: [], selectedId: null, draggingMaster: null, display: DEFAULT_CALENDAR_DISPLAY, centerRequest: 0, focusDate: null, initialExpandedContractIds: [contrato.id], onSelect: () => {}, onSelectMasters: () => {}, onSelectMaster: () => {}, onOpenContract: () => {}, onDropMaster: () => {}, onResizeMasterPreview: () => {}, onResizeMasterCommit: () => {}, onResizeMasterCancel: () => {}, onFocusDate: () => {} }; const dayMarkup = renderToStaticMarkup(createElement(GanttGrid, { ...props, zoom: 'day' })); const weekMarkup = renderToStaticMarkup(createElement(GanttGrid, { ...props, zoom: 'week' })); const collapsedDayMarkup = renderToStaticMarkup(createElement(GanttGrid, { ...props, initialExpandedContractIds: [], zoom: 'day' })); const childDayTimelines = dayMarkup.match(/co-grid-row--child[\s\S]*?co-row-timeline"><div class="co-day-timeline/g) ?? []; const childWeekTimelines = weekMarkup.match(/co-grid-row--child[\s\S]*?co-row-timeline"><div class="co-week-timeline/g) ?? []; assert.equal(childDayTimelines.length, 2); assert.equal(childWeekTimelines.length, 2); assert.match(collapsedDayMarkup, /co-contract-calendar"><div class="co-day-timeline/); assert.equal((dayMarkup.match(/co-day-cell/g) ?? []).length, 0); assert.equal((weekMarkup.match(/co-week-cell/g) ?? []).length, 0); const styles = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/styles/cronograma-obras.css'), 'utf8'); assert.match(styles, /\.co-week-timeline\s*\{[^}]*background:\s*var\(--co-week-grid\)/); assert.match(styles, /\.co-row-timeline\s*\{[^}]*min-height:\s*inherit/); });
test('LOTE sem dados opcionais não cria text nodes numéricos entre OBRA e MESTRES', () => { const obra = { ...fixtureObra('lote-sem-opcionais'), contratoId: 'contrato-lote', nomeObra: 'LOTE sem opcionais', empresa: '', inicioPlanejado: null, tempoPlanejado: null, mestresPlanejados: [] }; const contrato = { id: 'contrato-lote', nome: 'Contrato de teste', empresa: '', status: 'PENDENTE', numeroContrato: null, ano: null, inicio: null, fim: null, tipoObra: null, confirmacaoRecurso: null, ordemInicio: null, obraV2Id: null, rawDocument: null, obras: [obra] }; const markup = renderToStaticMarkup(createElement(GanttGrid, { view: 'obras', zoom: 'year', years: [2026], obras: [obra], contratos: new Map([[contrato.id, contrato]]), workloads: [], selectedId: null, draggingMaster: null, display: DEFAULT_CALENDAR_DISPLAY, centerRequest: 0, focusDate: null, initialExpandedContractIds: [contrato.id], onSelect: () => {}, onSelectMasters: () => {}, onSelectMaster: () => {}, onOpenContract: () => {}, onDropMaster: () => {}, onResizeMasterPreview: () => {}, onResizeMasterCommit: () => {}, onResizeMasterCancel: () => {}, onFocusDate: () => {} })); const row = [...markup.matchAll(/<div class="co-row-info co-left-row">([\s\S]*?)<\/div><div class="co-row-timeline">/g)].map((match) => match[1]).find((cells) => cells.includes('LOTE sem opcionais')); assert.ok(row); assert.doesNotMatch(row, />0</); const work = row.indexOf('co-work-name'); const masters = row.indexOf('co-masters-cell'); const status = row.indexOf('co-status'); const start = row.indexOf('co-start-date'); const days = row.lastIndexOf('>—</span>'); assert.ok(work >= 0 && work < masters && masters < status && status < start && start < days); });

test('Obra iniciada mantém o toggle e a geometria compacta inclui Início sem Status ou Emp.', () => { const gantt = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/components/GanttGrid.tsx'), 'utf8'); const columns = readFileSync(resolve(process.cwd(), 'src/features/cronograma-obras/domain/obraGridColumns.ts'), 'utf8'); assert.match(gantt, /className="co-columns-toggle"/); assert.match(gantt, /\{detailsVisible \? \(\s*<>\s*<span>Início<\/span>\s*<span>Dias<\/span>[\s\S]*\) : \(\s*<span>Início<\/span>/); assert.match(gantt, /!detailsVisible && <button[\s\S]*co-start-date/); assert.match(gantt, /<b aria-label=\{`\$\{group\.obras\.length\} obras`\}>\{group\.obras\.length\}<\/b>/); assert.doesNotMatch(gantt, /MoreVertRounded|co-contract-details/); assert.match(columns, /STARTED_FLAT_COLLAPSED_COLUMNS[\s\S]*nomeContrato[\s\S]*obra[\s\S]*mestres[\s\S]*inicio/); assert.match(columns, /STARTED_CONTRACT_COLLAPSED_COLUMNS/); });
